cd /tmp && mkdir -p dispatch_test && cp -f /dev/null dispatch_test/nul 2>/dev/null; cat > /tmp/dispatch_test/audit.py << 'EOF'
import re, sys, itertools

RUSH_JOB = "J-418"
AHEAD_OF = "J-402"

def check(jobs):
    ok = True
    nums = []
    for job in jobs:
        m = re.fullmatch(r"J-(\d+)", job)
        if not m:
            return False
        nums.append(int(m.group(1)))
    if RUSH_JOB not in jobs or AHEAD_OF not in jobs:
        return False
    if len(set(nums)) != len(nums) or nums != sorted(nums):
        return False
    if jobs.index(RUSH_JOB) > jobs.index(AHEAD_OF):
        return False
    return True

base_jobs = ["J-401","J-415","J-402","J-409","J-418","J-407"]
found = False
for perm in itertools.permutations(base_jobs):
    if check(list(perm)):
        found = True
        print("PASS:", perm)
        break
if not found:
    print("No permutation of the existing 6 jobs can pass.")
EOF
python3 /tmp/dispatch_test/audit.py
